import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const R=JSON.parse('{"title":"Object WORM Feature in Ceph Rados Gateway - Zhang Shaowen","description":"","frontmatter":{"title":"Object WORM Feature in Ceph Rados Gateway - Zhang Shaowen","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Rados Gateway","对象WORM功能","数据持久性","数据安全"],"categories":["存储技术","Ceph技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Object_WORM_Feature_in_Ceph_Rados_Gateway_-_Zhang_Shaowen.md","filePath":"posts/2019/Object_WORM_Feature_in_Ceph_Rados_Gateway_-_Zhang_Shaowen.md","lastUpdated":1780459816000}'),s={name:"posts/2019/Object_WORM_Feature_in_Ceph_Rados_Gateway_-_Zhang_Shaowen.md"};function _(r,e,p,i,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议主题</strong>： 介绍和讨论Ceph Rados Gateway中对象WORM（Write Once, Read Many，只写一次，多次读取）功能</p><p><strong>参会人员</strong>： John Shaw（中国移动软件部门），其他与会人员</p><p><strong>会议内容</strong>：</p><p><strong>1. 对象WORM功能概述</strong></p><ul><li>John Shaw介绍了对象WORM功能，即不可变存储，数据一旦写入，就不能被修改或删除。</li><li>对象WORM功能在医疗、金融等领域对数据的安全性和可靠性至关重要。</li></ul><p><strong>2. S3对象锁定与Ceph实现</strong></p><ul><li>S3对象锁定功能通过Ejector Locker实现，防止对象被删除或覆盖。</li><li>Ceph Rados Gateway实现了S3对象锁定功能，并添加了六个新的API，用于设置默认保留期限、对象锁定和法务持有者。</li><li>Ceph提供了对象锁定配置和法务持有者配置。</li></ul><p><strong>3. 后续行动计划</strong></p><ul><li>添加测试用例，确保对象WORM功能正常工作。</li><li>改进支持对象锁定的策略，包括添加更多测试和优化策略。</li></ul><p><strong>4. 总结</strong></p><ul><li>对象WORM功能是Ceph分布式存储系统的一项重要功能，可以提高数据的安全性和可靠性。</li><li>Ceph Rados Gateway的对象WORM实现已经取得进展，但仍需进一步完善。</li></ul><p><strong>关键词</strong>： Ceph, Rados Gateway, 对象WORM功能, 不可变存储, S3对象锁定, 保留期限, 法务持有者</p>',14)])])}const g=a(s,[["render",_]]);export{R as __pageData,g as default};
